#pragma once

// JusPrin's own update check. It reads JusPrin's release list on GitHub at
// startup and then once a day, and when the person asks with Check now. It
// only finds out: the release page is opened by the person, and nothing is
// downloaded or installed.

#include "ReleaseFeed.hpp"

#include <ctime>
#include <functional>
#include <map>
#include <memory>
#include <optional>
#include <string>

class wxTimer;

namespace Slic3r::GUI {
class MainFrame;
}

namespace Slic3r::GUI::JusPrin::Updates {

class UpdateCheck
{
public:
    enum class Status {
        NotChecked,
        Checking,
        UpToDate,
        Available, // a newer release was found, at the last check or an earlier one
        Failed,    // the last check could not read the release list
        Store,     // a Microsoft Store install: the Store updates it, JusPrin does not check
    };

    struct State
    {
        Status                 status{Status::NotChecked};
        std::string            version; // the running JusPrin
#pragma once

// Reads JusPrin's release list as GitHub's REST API returns it
// (GET /repos/TheSpaghettiDetective/JusPrin/releases). GUI-free.

#include <optional>
#include <stdexcept>
#include <string>

namespace Slic3r::GUI::JusPrin::Updates {

struct Release
{
    std::string version;   // "2.1.0", from the tag
    std::string url;       // the release page
    std::string published; // when it was published, as GitHub gives it
    std::string notes;     // the release notes, in Markdown, cut to at most kNotesLimit bytes
};

inline constexpr std::size_t kNotesLimit = 16 * 1024;

// The version a release tag names: "v2.1.0" and "jusprin/v2.1.0" both give
// "2.1.0". Empty when the tag names no version, as "nightly-builds" does.
std::string tag_version(const std::string& tag);

// What came back was not GitHub's release list.
struct FeedError : std::runtime_error
{
    using std::runtime_error::runtime_error;
};
