55	// Installs the JusPrin production presentation inside the existing MainFrame
56	// layout and can restore the stock presentation exactly. The stock widget
57	// hierarchy stays constructed and functional: the Notebook keeps its pages and
58	// selection flow, only its tab strip is hidden, and the Plater sidebar is held
59	// hidden through Plater's sidebar-availability policy.
60	class ShellController : public wxEvtHandler
61	{
62	public:
63	    enum class ReimportDecision { OpenExisting, CreateNew, Cancel };
64	    ShellController();
65	    ~ShellController();
66	
67	    ShellController(const ShellController&) = delete;
68	    ShellController& operator=(const ShellController&) = delete;
69	
70	    // The open project's conversation as the shell leaves it, and what tells
71	    // that project apart from the next one OrcaSlicer opens or starts.
72	    struct OpenProject
73	    {
74	        std::uint64_t project_session{0};
75	        std::string   auxiliary_dir;
76	        std::string   state;
77	    };
78	
79	    // Throws on failure after restoring any partial change; the caller may
80	    // then continue with the untouched stock presentation. A shell installed
81	    // over the project an earlier one left takes up its conversation.
82	    void install(MainFrame& frame, Notebook& tabpanel, wxSizer& main_sizer,
83	                 const std::optional<OpenProject>& left = std::nullopt);
84	    void uninstall();
85	    OpenProject open_project() const;
86	    bool is_installed() const { return m_installed; }
87	
88	    StatusRow* status_row() const { return m_status_row; }
89	    Home::HomeWebView* home_view() const { return m_home; }
90	    PrinterSetup::PrinterPanel* printer_panel() const { return m_printer_panel; }
91	    AgentPane* agent_pane() const { return m_agent_pane; }
92	    PrintIssues::WorkFeed* work_feed() const { return m_work_feed.get(); }
93	    bool agent_pane_collapsed() const { return m_agent_pane_collapsed; }
94	    LeftPane* left_pane() const { return m_left_pane; }
95	    // The Prepare canvas's presentation, for the integration harness to drive
96	    // the tool strip and the value card the way a pointer does.
97	    const CanvasPresentationController& prepare_canvas_presentation() const { return m_prepare_canvas_presentation; }
98	    Workspace::IWorkspace* workspace() const { return m_workspace.get(); }
99	
100	    // What OrcaSlicer currently reports about the active plate, and its
101	    // pill, list and bubble on the Prepare canvas. Null while not installed.
102	    PrintIssues::PrintIssueMonitor* print_issues() const { return m_print_issues.get(); }
103	    PrintIssues::IssueOverlay*      issue_overlay() const { return m_issue_overlay.get(); }
104	    struct IssueSubmission
105	    {
106	        // "started", "queued", "duplicate", or why nothing was sent:
107	        // "expired" (OrcaSlicer no longer reports the issue), "unchecked"
108	        // (it has not validated the latest edit), "agent_not_set_up" (there
109	        // is no assistant to answer), "busy" (a reply is being written), or
110	        // the chat's own refusal code.
111	        std::string               outcome;
112	        PrintIssues::IssueMessage message;
113	    };
114	    // Sends the issue to the project chat as the person's own message and
115	    // opens the chat pane. The issue is looked up again at the moment of the
116	    // press, so one that has cleared or gone stale since it was drawn is not sent.
117	    IssueSubmission submit_issue(const std::string& issue_id, const std::string& request_sentence);
118	    // A Calibrate… row (printer chip, filament slot, Home printer card):
119	    // board 3's one popup first, since the open project closes; on Start
120	    // the app opens the calibration project and its chat. filament is empty
121	    // for a Home printer card, whose loaded spools (as it reports them) the
122	    // Agent offers instead.
123	    void start_calibration(const std::string& printer, const std::string& filament,
124	                           const std::vector<std::string>& spools = {});
125	    // The page's answer to start_calibration's question.
126	    void answer_calibration(const std::string& request_id, bool confirmed);
127	    Agent::ProjectPersistence* persistence() const { return m_persistence.get(); }
128	    Workspace::ProjectAutosave* autosave() const { return m_autosave.get(); }
129	    void set_reimport_confirmation(std::function<ReimportDecision()> confirmation)
130	        { m_reimport_confirmation = std::move(confirmation); }
131	    // How a file is opened (architecture.md, "Opening and
132	    // importing files"). Dropped on the Prepare canvas, a model file is added
133	    // to the open project; the canvas's drop target calls add_dropped_files.
134	    // Home's Open… and a drop on Home call open_files_as_new_project: a model
135	    // file (or a zip of them) opens in a new project named after it. A .3mf
136	    // opens as a project either way, through OrcaSlicer's load_project and
137	    // its "Previously opened file" question. The harness calls both.
138	    bool add_dropped_files(const wxArrayString& files);
139	    bool open_files_as_new_project(const wxArrayString& files);
140	
141	    void apply_current_appearance();
142	
143	    // Closing the Agent panel hides it and its divider; the panel keeps its
144	    // conversation, its loaded page, and its MCP runtime while hidden, and
145	    // reopening restores the width it last held this session.
146	    void set_agent_pane_collapsed(bool collapsed);
147	    // A person's own choice, remembered across the visits to Home that
148	    // collapse the pane on their behalf.
149	    void toggle_agent_pane()
150	    {
151	        m_agent_pane_user_collapsed = !m_agent_pane_collapsed;
152	        set_agent_pane_collapsed(m_agent_pane_user_collapsed);
153	    }
154	    bool is_agent_pane_collapsed() const { return m_agent_pane_collapsed; }
155	    // Mirrored left-panel treatment: the open copy lives in its own header
156	    // row; the collapsed copy lives at the same screen edge in Project header.
157	    void set_left_pane_collapsed(bool collapsed);
158	    void toggle_left_pane() { set_left_pane_collapsed(!m_left_pane_collapsed); }
159	    bool is_left_pane_collapsed() const { return m_left_pane_collapsed; }
160	    // JusPrin's Preferences window, over whatever is on screen; returns once
161	    // it is closed. `section` names where it opens (empty: Account). Its
162	    // Agent section is the one place the agent is set up: every surface that
163	    // finds none opens it there, and picks the agent up when it closes.
164	    // `closed`, when given, opens it for one task and hears how it ended: the
165	    // window then closes itself once a verified key is saved ("key") or Done
166	    // is pressed on an AI tool ("tool"), and `closed` gets that word, or an
167	    // empty one when the person closed it first.
168	    using PreferencesClosed = std::function<void(const std::string& done)>;
169	    void open_preferences(const std::string& section = {}, PreferencesClosed closed = {});
170	    // Opens it on the frame's next turn, for a caller that must not run a
171	    // modal window itself (a web view's message handler, a key handler).
172	    // Requests that arrive before it opens open it once.
173	    void request_preferences(const std::string& section = {}, PreferencesClosed closed = {});
174	    // The agent settings changed outside Preferences (Home's sign-in): the
175	    // docked agent, and an open printer chat, pick them up.
176	    void reload_agent_settings();
177	    // The window shown once after JusPrin v1's setup was imported at this
178	    // start (V1Import.hpp); returns once it is closed. Nothing when there is
179	    // no import still to show.
180	    void open_welcome_back();
181	    // File › Import › Import from OrcaSlicer… (Home/OrcaImportWindow.hpp);
182	    // returns once it is closed.
183	    void open_orca_import();
184	
185	    // Orca's own printer wizard ("set it up myself") runs from a CallAfter,
186	    // decoupled from the add-printer request that opened it, so nothing else
187	    // tells Home about the printer it names. The caller asks for this refresh
188	    // once the wizard flow (and any naming it does) has actually finished.
189	    // `added` is a successful Add's saved facts, forwarded so Home can lead
190	    // its column with that printer and say what it assumed; every other
191	    // caller passes none.
192	
193	    // Opens a fresh temporary task chat over the current workspace. The
194	    // Notebook keeps its selection, so Back restores the same Home, Prepare,
195	    // or Preview screen without rebuilding it.
196	    void open_printer_conversation(const std::string& printer_name = {}, bool connect = false);
197	    // Opens a filament's chat for one slot. `preset` is the slot's filament
198	    // preset by name; `shown` is what the header calls it.
199	    void open_filament_help(std::size_t slot, const std::string& preset, const std::string& shown);
200	
201	    // The Print history screen, a leaf of Home and of the project: opened
202	    // from the project (its pane row, a chat marker's link), it is filtered
203	    // to the open project and shows `focus_hash`'s entry; Back returns to the
204	    // screen it was opened from. On the frame's next turn, since both ways in
205	    // are a pane's or a web view's own handler.
206	    void open_print_history(const std::string& focus_hash = {});
207	    void leave_print_history();
208	    // A project's chat at one of its items: opens the project when another
209	    // is open, then the chat, scrolled to the item. On the frame's next turn.
210	    void open_in_chat(const std::string& project_id, const std::string& conversation_id, const std::string& item_id);
211	    GcodeHistoryRecorder* gcode_history() const { return m_gcode_history.get(); }
212	    // Print again for a recorded G-code: OrcaSlicer's send dialog for its kept
213	    // file, on the frame's next turn (the Print history page asks for it).
214	    void print_again(const std::string& project_id, const std::string& hash);
215	
216	private:
217	    // OrcaSlicer's load_files(wxArrayString) hands a person's files here
218	    // first (Plater::set_external_file_open_handler): files from the OS,
219	    // another instance, the command line, a download, and the two calls
220	    // above. True when it opened them in a new project, or the open stopped;
221	    // false leaves them to OrcaSlicer, which opens a .3mf as a project and
222	    // adds the rest.
223	    bool take_opened_files(const std::vector<boost::filesystem::path>& files);
224	    // OrcaSlicer puts its own drop target back after every slice; the
225	    // canvas's is put back on the next idle turn.
226	    void on_plater_idle(wxIdleEvent& event);
227	    void install_drop_target();
228	    bool m_adding_files{false};
229	    // File > Import > Import Zip Archive goes through load_files too, so a
230	    // lone zip adds unless it came through open_files_as_new_project.
231	    bool m_zip_opens_project{false};
232	    void on_frame_destroy(wxWindowDestroyEvent& event);
233	    // print_dialog_open: refuses, or opens the send dialog on the next turn.
234	    Agent::ToolExecutionCoordinator::PrintDialogOutcome
235	    open_print_dialog(const Agent::ToolExecutionCoordinator::PrintDialogRequest& request);
236	    // Every saved project's G-code records, the open one's included.
