        check(enabled(menus->help_menu(), _L("Ask AI…")), "app_menus_ask_ai_works_from_home");
#ifdef __APPLE__
        check(menus->view_menu()->FindItemByPosition(2)->GetItemLabelText() == _L("Show AI panel"),
